import java.util.*;

class Solution {
  public List<Integer> killProcess(List<Integer> pid, List<Integer> ppid, int kill) {
    Map<Integer, List<Integer>> children = new HashMap<>();
    for (int i = 0; i < pid.size(); i++) children.computeIfAbsent(ppid.get(i), k -> new ArrayList<>()).add(pid.get(i));
    List<Integer> res = new ArrayList<>();
    Deque<Integer> q = new ArrayDeque<>();
    q.add(kill);
    while (!q.isEmpty()) {
      int p = q.poll();
      res.add(p);
      q.addAll(children.getOrDefault(p, Collections.emptyList()));
    }
    return res;
  }
}
